<?php

namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Str;
use Illuminate\Support\Facades\Storage;

class PortalController extends Controller {
 private function company():int{$configured=(int)config('app.public_portal_company_id',0);if($configured&&DB::table('companies')->where(['id'=>$configured,'status'=>'active'])->exists())return$configured;$id=DB::table('companies')->where('status','active')->orderBy('id')->value('id');abort_unless($id,503,'No existe una empresa activa para el portal');return(int)$id;}
 private function portalConfig():array{$values=DB::table('settings')->where(['company_id'=>$this->company(),'group'=>'portal'])->pluck('value','key');$phone=$values['contact_phone']??'';$company=DB::table('companies')->where('id',$this->company())->first();$num=fn($k)=>is_numeric($values[$k]??null)?(float)$values[$k]:null;
  return['enabled'=>($values['enabled']??'1')==='1','mode'=>$values['mode']??'shop','show_stock'=>($values['show_stock']??'1')==='1','delivery_zone'=>$values['delivery_zone']??'Piura Centro','contact_phone'=>$phone==='null'?'':$phone,'order_expiration_hours'=>(int)($values['order_expiration_hours']??24),
   // Entregas: recojo en tienda y/o delivery, con costo de envío y envío gratis desde cierto monto.
   'pickup_enabled'=>($values['pickup_enabled']??'1')==='1','delivery_enabled'=>($values['delivery_enabled']??'1')==='1','delivery_fee'=>max(0,$num('delivery_fee')??0),'free_delivery_from'=>max(0,$num('free_delivery_from')??0),
   'pickup_address'=>($values['pickup_address']??'')?:($company->address??''),'pickup_hours'=>$values['pickup_hours']??'','store_lat'=>$num('store_lat'),'store_lng'=>$num('store_lng'),
   // Ciudad donde se reparte (centra el mapa y acota la búsqueda) y radio máximo desde la tienda (0 = sin límite).
   'delivery_city'=>trim((string)($values['delivery_city']??''))?:'Piura','delivery_radius_km'=>max(0,$num('delivery_radius_km')??0)];}
 private static function distanceKm(float $lat1,float $lng1,float $lat2,float $lng2):float{$r=deg2rad(...);$a=sin(($r($lat2)-$r($lat1))/2)**2+cos($r($lat1))*cos($r($lat2))*sin(($r($lng2)-$r($lng1))/2)**2;return 6371*2*asin(min(1,sqrt($a)));}
 private function requirePortal():array{$config=$this->portalConfig();abort_unless($config['enabled'],503,'El portal público está temporalmente desactivado');return$config;}
 // El portal vende desde el almacén de venta de la primera sucursal activa: catálogo, ficha y pedido usan el mismo stock.
 private function saleWarehouse():object{$c=$this->company();$branch=(int)DB::table('branches')->where(['company_id'=>$c,'status'=>'active'])->orderBy('id')->value('id');abort_unless($branch,503,'La tienda no tiene una sucursal activa');return$this->branchWarehouse($c,$branch);}
 private function reservedIn(int $warehouse){return DB::table('stock_reservations')->selectRaw('product_id,SUM(quantity) reserved')->where(['status'=>'active','warehouse_id'=>$warehouse])->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->groupBy('product_id');}
 private function imageUrl(?int $id):?string{return $id?url("/api/v1/portal/product-images/{$id}"):null;}
 // Imagen principal (o la primera) de cada producto, como subconsulta.
 private function primaryImage():\Illuminate\Database\Query\Expression{return DB::raw('(select i.id from product_images i where i.product_id=p.id order by i.is_primary desc,i.sort_order,i.id limit 1) as image_id');}
 private function presentationsOf():\Illuminate\Support\Collection{return app(\App\Services\ProductPresentationService::class)->forCompany($this->company());}
 private function presentationList($all,int $id){return $all->get($id,collect())->map(fn($x)=>['id'=>$x->id,'name'=>$x->name,'factor'=>(float)$x->factor,'sale_price'=>(float)$x->sale_price])->values();}
 public function home(){$config=$this->portalConfig();$c=$this->company();$enabled=$config['enabled'];return response()->json(['success'=>true,'data'=>['portal'=>$config,
  // Solo datos públicos de la empresa.
  'company'=>DB::table('companies')->where('id',$c)->select('trade_name','business_name','address','phone','email','logo')->first(),
  'appearance'=>\App\Support\Appearance::for($c),'banners'=>$enabled?$this->banners($c):[],
  'categories'=>$enabled?DB::table('categories')->where(['company_id'=>$c,'status'=>'active'])->whereNull('parent_id')->orderBy('sort_order')->orderBy('name')->select('id','name')->get():[],
  'brands'=>$enabled?DB::table('products')->where(['company_id'=>$c,'status'=>'active'])->whereNotNull('brand')->where('brand','!=','')->distinct()->orderBy('brand')->pluck('brand'):[],
  'promotions'=>$enabled?DB::table('promotions')->where(['company_id'=>$c,'status'=>'active'])->where('starts_at','<=',now())->where('ends_at','>=',now())->select('id','name','type','value','ends_at')->get():[]]]);}
 public function catalog(Request $r){$this->requirePortal();$c=$this->company();$w=$this->saleWarehouse();$r->validate(['sort'=>'nullable|in:name,price_asc,price_desc,newest','per_page'=>'nullable|integer|min:1|max:48']);
  $q=DB::table('products as p')->join('stocks as s',fn($j)=>$j->on('s.product_id','=','p.id')->where('s.warehouse_id',$w->id))->leftJoinSub($this->reservedIn($w->id),'r','r.product_id','=','p.id')->where(['p.company_id'=>$c,'p.status'=>'active'])->whereRaw('s.quantity-COALESCE(r.reserved,0)>0')
   ->select('p.id','p.sku','p.name','p.category','p.brand','p.unit_type','p.sale_price',DB::raw('s.quantity-COALESCE(r.reserved,0) as stock'),$this->primaryImage());
  if($term=trim((string)$r->search))$q->where(fn($x)=>$x->where('p.name','like',"%{$term}%")->orWhere('p.sku','like',"%{$term}%")->orWhere('p.barcode',$term)->orWhere('p.brand','like',"%{$term}%"));
  if($r->category)$q->where('p.category',$r->category);if($r->brand)$q->where('p.brand',$r->brand);if($r->boolean('featured'))$q->where('p.is_featured',true)->orderBy('p.featured_order');
  match($r->sort){'price_asc'=>$q->orderBy('p.sale_price'),'price_desc'=>$q->orderByDesc('p.sale_price'),'newest'=>$q->orderByDesc('p.id'),default=>$q->orderBy('p.name')};
  $page=$q->paginate((int)($r->per_page??24));$presentations=$this->presentationsOf();
  $page->getCollection()->transform(function($p)use($presentations){$p->image=$this->imageUrl($p->image_id);unset($p->image_id);$p->stock=(float)$p->stock;$p->presentations=$this->presentationList($presentations,$p->id);return$p;});
  return response()->json(['success'=>true,'data'=>$page]);}
 public function product(int $id){$config=$this->requirePortal();$c=$this->company();$w=$this->saleWarehouse();
  // Solo campos públicos: nunca el costo ni el precio mínimo.
  $p=DB::table('products as p')->leftJoin('stocks as s',fn($j)=>$j->on('s.product_id','=','p.id')->where('s.warehouse_id',$w->id))->leftJoinSub($this->reservedIn($w->id),'r','r.product_id','=','p.id')->where(['p.id'=>$id,'p.company_id'=>$c,'p.status'=>'active'])
   ->select('p.id','p.sku','p.barcode','p.name','p.category','p.brand','p.unit_type','p.sale_price',DB::raw('CASE WHEN COALESCE(s.quantity,0)-COALESCE(r.reserved,0)>0 THEN COALESCE(s.quantity,0)-COALESCE(r.reserved,0) ELSE 0 END as stock'))->firstOrFail();
  $p->stock=(float)$p->stock;$p->portal=$config;$p->presentations=$this->presentationList($this->presentationsOf(),$p->id);
  $p->images=DB::table('product_images')->where('product_id',$id)->orderByDesc('is_primary')->orderBy('sort_order')->orderBy('id')->get()->map(fn($x)=>['id'=>$x->id,'url'=>$this->imageUrl($x->id),'alt'=>$x->alt,'is_primary'=>(bool)$x->is_primary]);
  $related=DB::table('product_relations as rel')->join('products as p','p.id','=','rel.related_product_id')->where('rel.product_id',$id)->where(['p.status'=>'active','p.company_id'=>$c])->select('p.id','p.name','p.sale_price','p.category','p.unit_type','rel.type',$this->primaryImage())->get();
  // Sin relaciones cargadas, se sugieren productos de la misma categoría.
  if($related->isEmpty())$related=DB::table('products as p')->where(['p.company_id'=>$c,'p.status'=>'active','p.category'=>$p->category])->where('p.id','!=',$id)->select('p.id','p.name','p.sale_price','p.category','p.unit_type',DB::raw("'similar' as type"),$this->primaryImage())->limit(4)->get();
  $p->related=$related->map(function($x){$x->image=$this->imageUrl($x->image_id);unset($x->image_id);return$x;});
  $p->promotions=DB::table('promotions as pr')->leftJoin('promotion_product as pp','pp.promotion_id','=','pr.id')->where(['pr.company_id'=>$c,'pr.status'=>'active'])->where('pr.starts_at','<=',now())->where('pr.ends_at','>=',now())->where(fn($q)=>$q->whereNull('pp.product_id')->orWhere('pp.product_id',$id))->select('pr.id','pr.name','pr.type','pr.value')->distinct()->get();
  return response()->json(['success'=>true,'data'=>$p]);}
 public function productImage(int$id){$img=DB::table('product_images as i')->join('products as p','p.id','=','i.product_id')->where(['i.id'=>$id,'p.company_id'=>$this->company(),'p.status'=>'active'])->select('i.*')->firstOrFail();abort_unless(Storage::exists($img->path),404);return Storage::response($img->path,null,['Cache-Control'=>'public,max-age=86400']);}
 public function bannerImage(int $id){$b=DB::table('portal_banners')->where(['id'=>$id,'company_id'=>$this->company(),'active'=>true])->whereNotNull('image_path')->firstOrFail();abort_unless(Storage::exists($b->image_path),404);return Storage::response($b->image_path,null,['Cache-Control'=>'public,max-age=86400']);}
 // Diapositivas vigentes; sin diapositivas propias, cada promoción activa se muestra como una.
 private function banners(int $c):\Illuminate\Support\Collection{$rows=DB::table('portal_banners as b')->leftJoin('products as p',fn($j)=>$j->on('p.id','=','b.product_id')->where('p.status','active'))->leftJoin('promotions as pr','pr.id','=','b.promotion_id')->where(['b.company_id'=>$c,'b.active'=>true])->where(fn($q)=>$q->whereNull('b.starts_at')->orWhere('b.starts_at','<=',now()))->where(fn($q)=>$q->whereNull('b.ends_at')->orWhere('b.ends_at','>=',now()))->orderBy('b.sort_order')->orderBy('b.id')
  ->select('b.id','b.title','b.subtitle','b.button_label','b.category','b.image_path','p.id as product_id','p.name as product_name','p.sale_price as product_price','pr.id as promotion_id','pr.name as promotion_name','pr.type as promotion_type','pr.value as promotion_value',DB::raw('(select i.id from product_images i where i.product_id=p.id order by i.is_primary desc,i.sort_order,i.id limit 1) as product_image_id'))->limit(10)->get()
  ->map(fn($b)=>['id'=>$b->id,'title'=>$b->title,'subtitle'=>$b->subtitle,'button_label'=>$b->button_label,'category'=>$b->category,'image'=>$b->image_path?url("/api/v1/portal/banner-images/{$b->id}"):$this->imageUrl($b->product_image_id),'own_image'=>(bool)$b->image_path,
   'product'=>$b->product_id?['id'=>$b->product_id,'name'=>$b->product_name,'sale_price'=>(float)$b->product_price]:null,'promotion'=>$b->promotion_id?['id'=>$b->promotion_id,'name'=>$b->promotion_name,'type'=>$b->promotion_type,'value'=>(float)$b->promotion_value]:null]);
  if($rows->isNotEmpty())return$rows;
  return DB::table('promotions')->where(['company_id'=>$c,'status'=>'active'])->where('starts_at','<=',now())->where('ends_at','>=',now())->orderBy('ends_at')->limit(5)->get()->map(fn($p)=>['id'=>'promo-'.$p->id,'title'=>$p->name,'subtitle'=>($p->type==='percentage'?(+$p->value).'% de descuento':($p->type==='fixed'?'S/ '.number_format((float)$p->value,2).' de descuento':'Oferta especial')).' · hasta el '.date('d/m',strtotime($p->ends_at)),'button_label'=>'Ver productos','category'=>null,'image'=>null,'own_image'=>false,'product'=>null,'promotion'=>['id'=>$p->id,'name'=>$p->name,'type'=>$p->type,'value'=>(float)$p->value]]);}
 public function order(Request $r){$config=$this->requirePortal();abort_unless($config['mode']==='shop',403,'El portal está configurado solo para consulta de stock');
  $types=array_keys(array_filter(['delivery'=>$config['delivery_enabled'],'pickup'=>$config['pickup_enabled']]));abort_if(!$types,422,'La tienda no tiene métodos de entrega activos en este momento.');
  $r->merge(['fulfillment_type'=>$r->input('fulfillment_type',$types[0])]);
  if($r->input('fulfillment_type')==='delivery'&&$config['delivery_radius_km']>0&&$config['store_lat']!==null){
   abort_if($r->input('delivery_lat')===null||$r->input('delivery_lng')===null,422,'Marca en el mapa el punto de entrega.');
   $km=self::distanceKm($config['store_lat'],$config['store_lng'],(float)$r->input('delivery_lat'),(float)$r->input('delivery_lng'));
   abort_if($km>$config['delivery_radius_km'],422,sprintf('La dirección está a %.1f km de la tienda; solo repartimos hasta %s km.',$km,rtrim(rtrim(number_format($config['delivery_radius_km'],1,'.',''),'0'),'.')));}
  $d=$r->validate(['fulfillment_type'=>['required',\Illuminate\Validation\Rule::in($types)],'delivery_district'=>'nullable|string|max:120','delivery_reference'=>'nullable|string|max:255','delivery_lat'=>'nullable|numeric|between:-90,90','delivery_lng'=>'nullable|numeric|between:-180,180','customer_notes'=>'nullable|string|max:500','customer_name'=>'required|string|max:120','customer_phone'=>['required','string','max:20','regex:/^[0-9+ ()-]{6,20}$/'],'delivery_address'=>'required_if:fulfillment_type,delivery|nullable|string|max:500','items'=>'required|array|min:1|max:60','items.*.product_id'=>'required|integer','items.*.quantity'=>'required|numeric|min:0.001','items.*.entry_mode'=>'nullable|in:quantity,amount','items.*.line_total'=>'nullable|numeric|min:0.01','items.*.presentation_id'=>'nullable|integer']);$token=$r->bearerToken();$web=$token?DB::table('web_customers')->where('api_token',hash('sha256',$token))->first():null;return DB::transaction(function()use($d,$web,$config){$items=[];$total=0;$requested=[];$warehouse=$this->saleWarehouse();foreach($d['items'] as $i){$p=DB::table('products')->where(['id'=>$i['product_id'],'company_id'=>$this->company(),'status'=>'active'])->firstOrFail();$mode=$i['entry_mode']??'quantity';$quantity=round((float)$i['quantity'],3);$presentation=null;$unitPrice=(float)$p->sale_price;if(!empty($i['presentation_id'])){$pr=app(\App\Services\ProductPresentationService::class)->find($this->company(),$p->id,(int)$i['presentation_id']);abort_if(fmod($quantity,1.0)!==0.0,422,"{$pr->name} de {$p->name} se pide en cantidades enteras");$presentation=['id'=>$pr->id,'name'=>$pr->name,'quantity'=>$quantity,'factor'=>(float)$pr->factor];$line=round($quantity*(float)$pr->sale_price,2);$unitPrice=round((float)$pr->sale_price/(float)$pr->factor,4);$quantity=round($quantity*(float)$pr->factor,3);$mode='presentation';}elseif($mode==='amount'){abort_unless(\App\Services\ProductPresentationService::allowsDecimals($p->unit_type),422,'El ingreso por importe solo aplica a productos vendidos por peso');$line=round((float)($i['line_total']??0),2);$expected=round($line/(float)$p->sale_price,3);abort_if(abs($quantity-$expected)>0.0005,422,"El peso no corresponde al importe solicitado para {$p->name}");$quantity=$expected;}else{$line=round($quantity*(float)$p->sale_price,2);}$stock=(float)DB::table('stocks')->where(['product_id'=>$p->id,'warehouse_id'=>$warehouse->id])->lockForUpdate()->value('quantity');$reserved=(float)DB::table('stock_reservations')->where(['product_id'=>$p->id,'warehouse_id'=>$warehouse->id,'status'=>'active'])->where(fn($q)=>$q->whereNull('expires_at')->orWhere('expires_at','>',now()))->sum('quantity');$requested[$p->id]=($requested[$p->id]??0)+$quantity;abort_if($stock-$reserved<$requested[$p->id],422,"Stock insuficiente para {$p->name}");$total+=$line;$items[]=['product_id'=>$p->id,'name'=>$p->name,'quantity'=>$quantity,'unit_price'=>$unitPrice,'entry_mode'=>$mode,'total'=>$line,'presentation'=>$presentation];}$delivery=$d['fulfillment_type']==='delivery';$fee=$delivery&&!($config['free_delivery_from']>0&&$total>=$config['free_delivery_from'])?round($config['delivery_fee'],2):0;$address=$delivery?$d['delivery_address']:'Recojo en tienda'.($config['pickup_address']?": {$config['pickup_address']}":'');
  $number='WEB-'.str_pad((string)(DB::table('web_orders')->where('company_id',$this->company())->lockForUpdate()->count()+1),6,'0',STR_PAD_LEFT);$id=DB::table('web_orders')->insertGetId(['uuid'=>Str::uuid(),'company_id'=>$this->company(),'customer_id'=>$web?->customer_id,'number'=>$number,'customer_name'=>$d['customer_name'],'customer_phone'=>$d['customer_phone'],'items'=>json_encode($items),'total'=>$total+$fee,'delivery_fee'=>$fee,'status'=>'pending','fulfillment_type'=>$d['fulfillment_type'],'delivery_address'=>$address,'delivery_district'=>$delivery?($d['delivery_district']??null):null,'delivery_reference'=>$delivery?($d['delivery_reference']??null):null,'delivery_lat'=>$delivery?($d['delivery_lat']??null):null,'delivery_lng'=>$delivery?($d['delivery_lng']??null):null,'customer_notes'=>$d['customer_notes']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('web_order_status_history')->insert(['web_order_id'=>$id,'new_status'=>'pending','notes'=>'Pedido recibido desde el portal','created_at'=>now(),'updated_at'=>now()]);foreach($items as $item)DB::table('stock_reservations')->insert(['company_id'=>$this->company(),'warehouse_id'=>$warehouse->id,'product_id'=>$item['product_id'],'quantity'=>$item['quantity'],'reference_type'=>'web_order','reference_id'=>$id,'expires_at'=>now()->addHours($config['order_expiration_hours']),'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Pedido registrado','data'=>['id'=>$id,'number'=>$number,'total'=>$total+$fee,'delivery_fee'=>$fee,'fulfillment_type'=>$d['fulfillment_type']]],201);});}
 public function track(Request $r,string $number){$this->requirePortal();$d=$r->validate(['phone'=>'required|string|min:6|max:30']);$order=DB::table('web_orders')->where(['number'=>strtoupper(trim($number)),'company_id'=>$this->company(),'customer_phone'=>trim($d['phone'])])->select('id','number','customer_name','fulfillment_type','delivery_address','delivery_district','delivery_reference','delivery_lat','delivery_lng','delivery_fee','items','total','status','payment_status','created_at','updated_at')->firstOrFail();$order->items=json_decode($order->items,true);$order->history=DB::table('web_order_status_history')->where('web_order_id',$order->id)->orderBy('created_at')->orderBy('id')->select('new_status as status','notes','created_at')->get();unset($order->id);return response()->json(['success'=>true,'data'=>$order]);}
 public function register(Request $r){$config=$this->requirePortal();abort_unless($config['mode']==='shop',403,'El portal está configurado solo para consulta de stock');$d=$r->validate(['name'=>'required','email'=>'required|email','phone'=>'nullable','password'=>'required|min:8']);abort_if(DB::table('web_customers')->where(['company_id'=>$this->company(),'email'=>$d['email']])->exists(),422,'El correo ya está registrado');return DB::transaction(function()use($d){$customerId=DB::table('customers')->insertGetId(['company_id'=>$this->company(),'name'=>$d['name'],'phone'=>$d['phone']??null,'email'=>$d['email'],'status'=>'active','created_at'=>now(),'updated_at'=>now()]);$id=DB::table('web_customers')->insertGetId(['company_id'=>$this->company(),'customer_id'=>$customerId,'name'=>$d['name'],'email'=>$d['email'],'phone'=>$d['phone']??null,'password'=>Hash::make($d['password']),'status'=>'active','created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Cuenta creada','data'=>['id'=>$id]],201);});}
 public function login(Request $r){$this->requirePortal();$d=$r->validate(['email'=>'required|email','password'=>'required']);$u=DB::table('web_customers')->where(['company_id'=>$this->company(),'email'=>$d['email'],'status'=>'active'])->first();abort_unless($u&&Hash::check($d['password'],$u->password),422,'Credenciales incorrectas');$token=Str::random(64);DB::table('web_customers')->where('id',$u->id)->update(['api_token'=>hash('sha256',$token),'updated_at'=>now()]);return response()->json(['success'=>true,'data'=>['token'=>$token,'user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email]]]);}
 private function web(Request $r):object{return $r->attributes->get('web_customer');}
 public function account(Request $r){$u=$this->web($r);return response()->json(['success'=>true,'data'=>['user'=>collect($u)->except(['password','api_token']),'orders'=>DB::table('web_orders')->where('customer_id',$u->customer_id)->latest()->limit(10)->get(),'addresses'=>DB::table('web_customer_addresses')->where('web_customer_id',$u->id)->get(),'favorite_ids'=>DB::table('web_favorites')->where('web_customer_id',$u->id)->pluck('product_id')]]);}
 public function logout(Request $r){DB::table('web_customers')->where('id',$this->web($r)->id)->update(['api_token'=>null,'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Sesión cerrada']);}
 public function profile(Request $r){$u=$this->web($r);$d=$r->validate(['name'=>'required','phone'=>'nullable']);DB::transaction(function()use($u,$d){DB::table('web_customers')->where('id',$u->id)->update($d+['updated_at'=>now()]);if($u->customer_id)DB::table('customers')->where('id',$u->customer_id)->update($d+['updated_at'=>now()]);});return response()->json(['success'=>true,'message'=>'Perfil actualizado']);}
 public function password(Request $r){$u=$this->web($r);$d=$r->validate(['current_password'=>'required','password'=>'required|min:8|confirmed']);abort_unless(Hash::check($d['current_password'],$u->password),422,'La contraseña actual no coincide');DB::table('web_customers')->where('id',$u->id)->update(['password'=>Hash::make($d['password']),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Contraseña actualizada']);}
 public function accountOrders(Request $r){$u=$this->web($r);return response()->json(['success'=>true,'data'=>DB::table('web_orders')->where('customer_id',$u->customer_id)->latest()->get()->map(function($x){$x->items=json_decode($x->items,true);return $x;})]);}
 public function addresses(Request $r){return response()->json(['success'=>true,'data'=>DB::table('web_customer_addresses')->where('web_customer_id',$this->web($r)->id)->get()]);}
 public function saveAddress(Request $r,?int $id=null){$u=$this->web($r);$d=$r->validate(['label'=>'required|string|max:60','address'=>'required|string|max:255','district'=>'nullable|string|max:120','city'=>'required|string|max:120','reference'=>'nullable|string|max:255','lat'=>'nullable|numeric|between:-90,90','lng'=>'nullable|numeric|between:-180,180','is_default'=>'boolean']);$d['web_customer_id']=$u->id;$d['updated_at']=now();if(!empty($d['is_default']))DB::table('web_customer_addresses')->where('web_customer_id',$u->id)->update(['is_default'=>false]);if($id)DB::table('web_customer_addresses')->where(['id'=>$id,'web_customer_id'=>$u->id])->update($d);else{$d['created_at']=now();$id=DB::table('web_customer_addresses')->insertGetId($d);}return response()->json(['success'=>true,'message'=>'Dirección guardada','data'=>['id'=>$id]]);}
 public function deleteAddress(Request $r,int $id){DB::table('web_customer_addresses')->where(['id'=>$id,'web_customer_id'=>$this->web($r)->id])->delete();return response()->json(['success'=>true,'message'=>'Dirección eliminada']);}
 public function favorites(Request $r){$u=$this->web($r);return response()->json(['success'=>true,'data'=>DB::table('web_favorites as f')->join('products as p','p.id','=','f.product_id')->where('f.web_customer_id',$u->id)->where(['p.company_id'=>$this->company(),'p.status'=>'active'])->select('p.id','p.name','p.sku','p.sale_price','p.category','p.unit_type',$this->primaryImage())->get()->map(function($x){$x->image=$this->imageUrl($x->image_id);unset($x->image_id);return$x;})]);}
 public function toggleFavorite(Request $r,int $product){$u=$this->web($r);abort_unless(DB::table('products')->where(['id'=>$product,'company_id'=>$this->company(),'status'=>'active'])->exists(),404,'Producto no disponible');$q=DB::table('web_favorites')->where(['web_customer_id'=>$u->id,'product_id'=>$product]);if($q->exists()){$q->delete();$active=false;}else{DB::table('web_favorites')->insert(['web_customer_id'=>$u->id,'product_id'=>$product,'created_at'=>now(),'updated_at'=>now()]);$active=true;}return response()->json(['success'=>true,'data'=>['active'=>$active]]);}
}
